using System;using System.IO;
class CleanupTests{static void Main(){string root=Path.Combine(Path.GetTempPath(),"BellCleanupTest-"+Guid.NewGuid().ToString("N")),data=Path.Combine(root,"app"),outside=Path.Combine(root,"outside");Directory.CreateDirectory(Path.Combine(data,"UserData","Sounds"));Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(outside,"keep.txt"),"keep");File.WriteAllText(Path.Combine(data,"UserData","settings.xml"),"settings");File.WriteAllText(Path.Combine(data,"UserData","Sounds","bell.wav"),"custom");bool rejected=false;try{ApplicationCleanup.RemoveTree(outside,data);}catch(IOException){rejected=true;}if(!rejected||!File.Exists(Path.Combine(outside,"keep.txt")))throw new Exception("Scope guard failed");ApplicationCleanup.RemoveTree(data,data);if(Directory.Exists(data)||!File.Exists(Path.Combine(outside,"keep.txt")))throw new Exception("Full cleanup failed");ApplicationCleanup.RemoveTree(data,data);Console.WriteLine("PASS: complete custom-data cleanup, repeat removal, and out-of-scope refusal; unrelated files preserved.");}}
